mapper.select:
select id, mix_area, machine_code, machine_name, class_shift, capacity, remark,status, del_flag, create_by,
create_time, update_by, update_time, mid_status, night_status, day_status from t_lhfl_machine
where del_flag = '0'
and mix_area = #{mixArea}
and status = #{status}
and INSTR(machine_name, #{machineName}) > 0

    order by machine_name


    order by ${orderStr}

WITH temp_table AS (

    SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType= VARCHAR}
    mix_area,#{data.machineCode,jdbcType= VARCHAR}
    machine_code 

)
select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy,
now() createTime
from t_lhfl_machine m
inner join temp_table t on m.mix_area = t.mix_area and m.machine_code = t.machine_code and m.del_flag ='0'

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType= VARCHAR} mix_area, #{data.machineName,jdbcType= VARCHAR} machine_name
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_lhfl_machine m inner join temp_table t on m.mix_area = t.mix_area and m.machine_name = t.machine_name and m.del_flag ='0'

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.mixArea,jdbcType= VARCHAR} mix_area, #{data.machineName,jdbcType= VARCHAR} machine_name, #{data.machineCode,jdbcType= VARCHAR} machine_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_lhfl_machine m inner join temp_table t on m.mix_area = t.mix_area and m.machine_name = t.machine_name and m.machine_code!=t.machine_code and m.del_flag ='0'

mapper.insert:
insert into t_lhfl_machine (id,mix_area,machine_code,machine_name,class_shift,capacity,remark,status,mid_status, night_status, day_status,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{lhflMachine.mixArea,jdbcType= VARCHAR} mix_area, #{lhflMachine.machineCode,jdbcType= VARCHAR} machine_code, #{lhflMachine.machineName,jdbcType= VARCHAR} machine_name, #{lhflMachine.classShift,jdbcType=DOUBLE} class_shift, #{lhflMachine.capacity,jdbcType=DOUBLE} capacity, #{lhflMachine.remark,jdbcType= VARCHAR} remark, #{lhflMachine.status,jdbcType=VARCHAR} status, #{mixMachine.midStatus,jdbcType=VARCHAR} mid_status, #{mixMachine.nightStatus,jdbcType=VARCHAR} night_status, #{mixMachine.dayStatus,jdbcType=VARCHAR} day_status, #{lhflMachine.delFlag,jdbcType= VARCHAR} del_flag, #{lhflMachine.createBy,jdbcType= VARCHAR} create_by, #{lhflMachine.createTime,jdbcType=TIMESTAMP} create_time, #{lhflMachine.updateBy,jdbcType= VARCHAR} update_by, #{lhflMachine.updateTime,jdbcType=TIMESTAMP} update_time
) x
